{"path": "/tmp/sv-b9ed2749125c4c43a61b6b6bfef4c7e0/Components/Pages/Board/KanbanBoard.razor", "file_text": "@page "/board"
@rendermode InteractiveServer
@using static KanbanColumn.MoveDirection
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (loading)
{
    <p class="loading">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error">@errorMessage</p>
}
else
{
    <BoardStats Total="allTasks.Count"
                TodoCount="todoTasks.Count"
                InProgressCount="inProgressTasks.Count"
                DoneCount="doneTasks.Count"
                OverdueCount="allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <div class="search-bar">
        <input type="text" placeholder="Search tasks by title..."
               @bind="searchTerm" @bind:event="oninput" />
    </div>

    <div class="kanban-board">
        <KanbanColumn ColumnName="To Do"
                      Tasks="filteredTodo"
                      ShowMoveLeft="false"
                      ShowMoveRight="true"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="args => HandleAddTask(args, \"To Do\")" />

        <KanbanColumn ColumnName="In Progress"
                      Tasks="filteredInProgress"
                      ShowMoveLeft="true"
                      ShowMoveRight="true"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="args => HandleAddTask(args, \"In Progress\")" />

        <KanbanColumn ColumnName="Done"
                      Tasks="filteredDone"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="args => HandleAddTask(args, \"Done\")" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private bool loading = true;
    private string? errorMessage;
    private string searchTerm = "";

    private List<TaskItem> todoTasks => allTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> inProgressTasks => allTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> doneTasks => allTasks.Where(t => t.Status == "Done").ToList();

    private List<TaskItem> filteredTodo => Filter(todoTasks);
    private List<TaskItem> filteredInProgress => Filter(inProgressTasks);
    private List<TaskItem> filteredDone => Filter(doneTasks);

    private List<TaskItem> Filter(List<TaskItem> tasks) =>
        string.IsNullOrWhiteSpace(searchTerm)
            ? tasks
            : tasks.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)).ToList();

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private async Task HandleMoveTask((int TaskId, KanbanColumn.MoveDirection Direction) args)
    {
        var task = allTasks.FirstOrDefault(t => t.Id == args.TaskId);
        if (task is null) return;

        var newStatus = (task.Status, args.Direction) switch
        {
            ("To Do", Right) => "In Progress",
            ("In Progress", Left) => "To Do",
            ("In Progress", Right) => "Done",
            ("Done", Left) => "In Progress",
            _ => task.Status
        };

        if (newStatus != task.Status)
        {
            try
            {
                await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
                var index = allTasks.IndexOf(task);
                allTasks[index] = task with { Status = newStatus };
            }
            catch (Exception ex)
            {
                errorMessage = $"Failed to move task: {ex.Message}";
            }
        }
    }

    private async Task HandleAddTask(
        (string Title, string Assignee, string Priority, DateTime DueDate) args,
        string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(args.Title, args.Assignee, args.Priority, args.DueDate);
            // The service returns the task; ensure it has the correct status
            allTasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}
"}

